INSERT INTO `announcements` (`id`, `user_id`, `title`, `content`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 1, 'Welcome to HR Management System', 'We are excited to announce our new HR Management System. Please take some time to explore the features and let us know your feedback.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(2, 1, 'Office Holiday Schedule', 'The office will be closed for the upcoming holidays. Please check the HR portal for the complete holiday schedule.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(3, 1, 'New Employee Benefits', 'We have updated our employee benefits package. Check the HR portal for details on health insurance and retirement plans.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(4, 1, 'System Maintenance Notice', 'The HR system will undergo maintenance this weekend. Expected downtime: Saturday 10 PM to Sunday 6 AM.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(5, 1, 'Town Hall Meeting Reminder', 'Don\'t forget our quarterly town hall meeting next Friday at 3 PM. All employees are encouraged to attend.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(6, 1, 'Updated Leave Policy', 'Our leave policy has been updated effective immediately. Please review the new guidelines in the employee handbook.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(7, 1, 'Welcome New Team Members', 'Please join us in welcoming our new team members who joined this month. Feel free to introduce yourself!', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(8, 1, 'Q1 Performance Review Period', 'Q1 performance reviews will begin next week. Please prepare your self-assessments and schedule meetings with your managers.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(9, 1, 'IT Security Update', 'Please update your passwords by end of this month. Follow the new password policy guidelines to ensure account security.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01'),
(10, 1, 'Company Anniversary Celebration', 'Join us in celebrating our company anniversary! The celebration party will be held next month. More details to follow.', 1, '2026-04-28 02:06:01', '2026-04-28 02:06:01');
